// The game catalog: every remastered game generated by studio/griddly-demo/tools/remaster (GDY +
// metadata JSON in ./remastered/), plus Spiders Garden. Everything is bundled at build time, so the
// library and player pages need no network beyond the engine itself.
import spidersGdy from "./minigrid-spiders-garden.yaml?raw";
import { gdyName, normaliseMeta, parseGdy, parseLevels } from "./gdy-meta";
import type { Camera, GameMeta, LevelInfo } from "./gdy-meta";

export type { Camera, GameMeta, HudItem, LevelInfo, Tone } from "./gdy-meta";
export { searchScore } from "./gdy-meta";

export type Game = GameMeta & {
  gdy: string;
  levels: LevelInfo[];
  /** Order in the catalog ("featured"). */
  rank: number;
};

// `import.meta.glob` is Vite's; bun's test runner lacks it, where the catalog is just Spiders Garden.
const safeGlob = <T>(glob: () => Record<string, T>): Record<string, T> => {
  try {
    return glob();
  } catch {
    return {};
  }
};
const metas = safeGlob(() =>
  import.meta.glob<Record<string, unknown>>("./remastered/*.json", { eager: true, import: "default" })
);
const gdys = safeGlob(() =>
  import.meta.glob<string>("./remastered/*.yaml", { query: "?raw", import: "default", eager: true })
);

const SPIDERS_META = {
  id: "spiders",
  name: "Spiders Garden",
  tagline: "Grab every gem. Don't get eaten.",
  description:
    "Collect every gem without touching a spider. Spiders wander at random and cocoon nests hatch more of them. Keys open doors; bridges cross the rivers.",
  tags: ["action", "exploration", "keys", "original"],
  difficulty: "medium",
  original: "Mini-Grid/minigrid-spiders.yaml",
  accent: "#34d399",
  icon: "🕷️",
  controls: { move: "move", extra: [] },
  hud: [
    { label: "Gems", kind: "collected", object: "gem", tone: "fuchsia" },
    { label: "Keys", kind: "var", object: "gnome", variable: "keys", tone: "amber" },
    { label: "Spiders", kind: "count", object: "spider", tone: "rose" },
  ],
  win_text: "All gems collected!",
  lose_text: "Eaten by a spider",
};

const stem = (path: string) => path.replace(/^.*\//, "").replace(/\.[^.]+$/, "");

const build = (raw: Record<string, unknown>, gdy: string, fallbackId: string): Omit<Game, "rank"> => ({
  ...normaliseMeta(raw, fallbackId, gdyName(gdy)),
  gdy,
  levels: parseLevels(gdy),
});

const remastered = Object.entries(gdys)
  .map(([path, gdy]) => {
    const id = stem(path);
    const meta = metas[`./remastered/${id}.json`] ?? {};
    return build(meta, gdy, id);
  })
  .filter((g) => g.levels.length > 0 && g.id !== "spiders")
  .sort((a, b) => a.name.localeCompare(b.name));

export const GAMES: Game[] = [build(SPIDERS_META, spidersGdy, "spiders"), ...remastered].map((g, rank) => ({
  ...g,
  rank,
}));

const BY_ID = new Map(GAMES.map((g) => [g.id, g]));
export const getGame = (id: string): Game | undefined => BY_ID.get(id);

/** Every tag in use, most common first. */
export const ALL_TAGS: string[] = (() => {
  const counts = new Map<string, number>();
  for (const g of GAMES) for (const t of g.tags) counts.set(t, (counts.get(t) ?? 0) + 1);
  return [...counts].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).map(([t]) => t);
})();

const gdyCache = new Map<string, ReturnType<typeof parseGdy>>();
/** Cameras (GDY render observers) and avatar of a game, parsed once. */
export const gameGdyInfo = (game: Game): { name: string; avatar: string; cameras: Camera[] } => {
  let info = gdyCache.get(game.id);
  if (!info) {
    info = parseGdy(game.gdy);
    gdyCache.set(game.id, info);
  }
  return info;
};
